public void onExplosion(ExplosionEvent.Start event) {
    float dist = 30;
    Vec3 center = event.getExplosion().getPosition();
    Vec3 bottom = center.add(-dist, -dist, -dist);
    Vec3 top = center.add(dist, dist, dist);
    Predicate<Entity> defusal = (animal) -> TameableUtils.isTamed(animal) && TameableUtils.hasEnchant((LivingEntity) animal, DIEnchantmentRegistry.DEFUSAL);
    boolean flag = false;
    for (LivingEntity defuser : event.getLevel().getEntitiesOfClass(LivingEntity.class, new AABB(bottom, top), EntitySelector.NO_SPECTATORS.and(defusal))) {
        float level = 10 * TameableUtils.getEnchantLevel(defuser, DIEnchantmentRegistry.DEFUSAL);
        if (defuser.distanceToSqr(center) <= level * level) {
            flag = true;
            break;
        }
    }
    if (flag) {
        event.setCanceled(true);
        float pitch = 1.5F + new Random().nextFloat();
        event.getLevel().playSound(null, center.x, center.y, center.z, SoundEvents.FIRE_EXTINGUISH, SoundSource.BLOCKS, 1, pitch);
        if (event.getLevel() instanceof ServerLevel serverLevel) {
            for (int i = 0; i < 5; i++) {
                serverLevel.sendParticles(ParticleTypes.CLOUD, center.x, center.y + 1.0F, center.z, 5, 0, 0F, 0, 0.2F);
            }
        }
    }
}

public static boolean isTamed(Entity entity) {
    //sometimes these are not bound on runtime
    if (entity instanceof Axolotl) {
        return ((ModifedToBeTameable) entity).isTame() && DomesticationMod.CONFIG.tameableAxolotl.get();
    }
    if (entity instanceof Fox) {
        return ((ModifedToBeTameable) entity).isTame() && DomesticationMod.CONFIG.tameableFox.get();
    }
    if (entity instanceof Rabbit) {
        return ((ModifedToBeTameable) entity).isTame() && DomesticationMod.CONFIG.tameableRabbit.get();
    }
    if (entity instanceof Frog) {
        return ((ModifedToBeTameable) entity).isTame() && DomesticationMod.CONFIG.tameableFrog.get();
    }
    return entity instanceof ModifedToBeTameable && ((ModifedToBeTameable) entity).isTame() || entity instanceof TamableAnimal && ((TamableAnimal) entity).isTame();
}

private static ListTag getEnchantmentList(LivingEntity entity) {
    CompoundTag tag = CitadelEntityData.getOrCreateCitadelTag(entity);
    if (tag.contains(ENCHANTMENT_TAG)) {
        return tag.getList(ENCHANTMENT_TAG, 10);
    }
    return null;
}

public static int getEnchantLevel(LivingEntity entity, Enchantment enchantment) {
    ListTag listtag = getEnchantmentList(entity);
    if (listtag != null && DomesticationMod.CONFIG.isEnchantEnabled(enchantment)) {
        for (int i = 0; i < listtag.size(); ++i) {
            CompoundTag compoundtag = listtag.getCompound(i);
            ResourceLocation res = EnchantmentHelper.getEnchantmentId(compoundtag);
            if (res != null && res.equals(ForgeRegistries.ENCHANTMENTS.getKey(enchantment))) {
                return EnchantmentHelper.getEnchantmentLevel(compoundtag);
            }
        }
    }
    return 0;
}

public static boolean hasEnchant(LivingEntity entity, Enchantment enchantment) {
    return getEnchantLevel(entity, enchantment) > 0;
}

public boolean isEnchantEnabled(Enchantment enchantment){
    return enchantment instanceof PetEnchantment && isEnchantEnabled(((PetEnchantment)enchantment).getName());
}

public boolean isEnchantEnabled(String enchantment){
    ForgeConfigSpec.BooleanValue entry = enabledEnchantments.get(enchantment);
    return entry == null || entry.get();
}

public DomesticationMod() {
    FMLJavaModLoadingContext.get().getModEventBus().addListener(this::setupClient);
    FMLJavaModLoadingContext.get().getModEventBus().addListener(this::setup);
    final ModLoadingContext modLoadingContext = ModLoadingContext.get();
    modLoadingContext.registerConfig(ModConfig.Type.COMMON, CONFIG_SPEC, "domestication-innovation.toml");
    DIItemRegistry.DEF_REG.register(FMLJavaModLoadingContext.get().getModEventBus());
    DIBlockRegistry.DEF_REG.register(FMLJavaModLoadingContext.get().getModEventBus());
    DIEnchantmentRegistry.registerEnchantments(FMLJavaModLoadingContext.get().getModEventBus());
    DITileEntityRegistry.DEF_REG.register(FMLJavaModLoadingContext.get().getModEventBus());
    DIEntityRegistry.DEF_REG.register(FMLJavaModLoadingContext.get().getModEventBus());
    DIPOIRegistry.DEF_REG.register(FMLJavaModLoadingContext.get().getModEventBus());
    DIParticleRegistry.DEF_REG.register(FMLJavaModLoadingContext.get().getModEventBus());
    DIVillagerRegistry.DEF_REG.register(FMLJavaModLoadingContext.get().getModEventBus());
    DISoundRegistry.DEF_REG.register(FMLJavaModLoadingContext.get().getModEventBus());
    DIActivityRegistry.DEF_REG.register(FMLJavaModLoadingContext.get().getModEventBus());
    DIVillagePieceRegistry.DEF_REG.register(FMLJavaModLoadingContext.get().getModEventBus());
    DICreativeTabRegistry.DEF_REG.register(FMLJavaModLoadingContext.get().getModEventBus());
    DILootRegistry.DEF_REG.register(FMLJavaModLoadingContext.get().getModEventBus());
    MinecraftForge.EVENT_BUS.register(this);
    MinecraftForge.EVENT_BUS.register(PROXY);
    PROXY.init();
}

public static void registerEnchantments(IEventBus bus) {
    try {
        for (Field f : DIEnchantmentRegistry.class.getDeclaredFields()) {
            Object obj = f.get(null);
            if (obj instanceof PetEnchantment petEnchantment) {
                DEF_REG.register(petEnchantment.getName(), () -> petEnchantment);
            }
        }
    } catch (IllegalAccessException e) {
        throw new RuntimeException(e);
    }
    DEF_REG.register(bus);
}

package com.github.alexthe668.domesticationinnovation.server.enchantment;

import com.github.alexthe668.domesticationinnovation.DomesticationMod;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.enchantment.Enchantment;

public class PetEnchantment extends Enchantment {

    private int levels;
    private int minXP;
    private String registryName;

    protected PetEnchantment(String name, Rarity r, int levels, int minXP) {
        super(r, DIEnchantmentRegistry.CATEGORY, new EquipmentSlot[]{EquipmentSlot.MAINHAND});
        this.levels = levels;
        this.minXP = minXP;
        this.registryName = name;
    }

    public int getMinCost(int i) {
        return minXP + (i - 1) * minXP;
    }

    public int getMaxCost(int i) {
        return super.getMinCost(i) + 5;
    }

    public int getMaxLevel() {
        return levels;
    }


    protected boolean checkCompatibility(Enchantment enchantment) {
        return this != enchantment && DIEnchantmentRegistry.areCompatible(this, enchantment);
    }

    public boolean isTradeable() {
        return super.isTradeable() && DomesticationMod.CONFIG.isEnchantEnabled(this);
    }

    public boolean isDiscoverable() {
        return super.isDiscoverable() && DomesticationMod.CONFIG.isEnchantEnabled(this);
    }

    public boolean isAllowedOnBooks() {
        return super.isAllowedOnBooks() && DomesticationMod.CONFIG.isEnchantEnabled(this);
    }

    public boolean canApplyAtEnchantingTable(ItemStack stack) {
        return super.canApplyAtEnchantingTable(stack) && DomesticationMod.CONFIG.isEnchantEnabled(this);
    }

    public String getName(){
        return registryName;
    }
}
